// ================= PENGATURAN TELEGRAM ================
const TELEGRAM_BOT_TOKEN = "YOUR_TELEGRAM_BOT_TOKEN";
const TELEGRAM_CHAT_ID   = "YOUR_TELEGRAM_CHAT_ID";
// =====================================================

// Hanya proses jika payload adalah sinyal ALERT dari Python
if (msg.payload && msg.payload.alert === true) {
    let imageBase64 = msg.payload.image;
    let timestamp = msg.payload.timestamp || Math.floor(Date.now() / 1000);
    let timeStr = new Date(timestamp * 1000).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' });
    let roomName = msg.payload.room_name || "Ruang Generator";

    let captionText = `🚨 <b>PERINGATAN RUANG GENSET</b> 🚨\n` +
                      `━━━━━━━━━━━━━━━━━━━━━\n` +
                      `⚠️ <b>Pelanggaran Two-Person Rule!</b>\n` +
                      `👤 <b>Status:</b> 1 Orang (Melebihi batas toleransi 5 detik)\n` +
                      `🕒 <b>Waktu:</b> ${timeStr} WIB\n` +
                      `📍 <b>Lokasi:</b> ${roomName}\n` +
                      `━━━━━━━━━━━━━━━━━━━━━\n` +
                      `<i>Segera kirimkan personel pendamping demi keselamatan kerja (K3)!</i>`;

    let alertMsg = { method: "POST" };

    if (imageBase64) {
        let boundary = '----WebKitFormBoundary' + Math.random().toString(36).substring(2);
        let imgBuffer = Buffer.from(imageBase64, 'base64');
        let parts = [];

        parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="chat_id"\r\n\r\n${TELEGRAM_CHAT_ID}\r\n`));
        parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="caption"\r\n\r\n${captionText}\r\n`));
        parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="parse_mode"\r\n\r\nHTML\r\n`));
        parts.push(Buffer.from(`--${boundary}\r\nContent-Disposition: form-data; name="photo"; filename="violation.jpg"\r\nContent-Type: image/jpeg\r\n\r\n`));
        parts.push(imgBuffer);
        parts.push(Buffer.from(`\r\n--${boundary}--\r\n`));

        alertMsg.url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendPhoto`;
        alertMsg.headers = { 'Content-Type': `multipart/form-data; boundary=${boundary}` };
        alertMsg.payload = Buffer.concat(parts);
        return alertMsg;
    } else {
        alertMsg.url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`;
        alertMsg.headers = { 'Content-Type': 'application/json' };
        alertMsg.payload = {
            chat_id: TELEGRAM_CHAT_ID,
            text: captionText,
            parse_mode: 'HTML'
        };
        return alertMsg;
    }
}

return null;
